from __future__ import annotations

from mq_models import PaymentMessage, QueueConfig, QueueSnapshot, payment_post
from queue_state import ProcessingState, audit, reset_for_retry, sorted_for_processing


def _audit(action: str, message: PaymentMessage, reason: str) -> dict[str, object]:
    return audit(action, message, reason)


def _reset_for_retry(message: PaymentMessage) -> PaymentMessage:
    return reset_for_retry(message)


def _post_payment(message: PaymentMessage) -> dict[str, object]:
    return payment_post(message)


def _validate_batch_size(messages: list[PaymentMessage], config: QueueConfig) -> None:
    if len(messages) > config.max_batch_size:
        raise ValueError("message batch exceeds max_batch_size")


def _process_single(
    message: PaymentMessage,
    config: QueueConfig,
    posted_ids: set[str],
    live_queue: list[PaymentMessage],
    backout_queue: list[PaymentMessage],
    successful_payments: list[dict[str, object]],
    audit_events: list[dict[str, object]],
) -> None:
    if message.valid_payload:
        if message.payment_id in posted_ids:
            audit_events.append(_audit("duplicate_success_skipped", message, "payment_already_posted"))
            return
        posted_ids.add(message.payment_id)
        successful_payments.append(_post_payment(message))
        audit_events.append(_audit("payment_posted", message, "valid_payload"))
        return

    failed_message = _reset_for_retry(message)
    if failed_message.backout_count >= config.backout_threshold:
        backout_queue.append(failed_message)
        audit_events.append(_audit("moved_to_backout", failed_message, "backout_threshold_reached"))
    else:
        live_queue.append(failed_message)
        audit_events.append(_audit("requeued_for_retry", failed_message, "payload_validation_failed"))


def process_mq_payments(
    messages: list[PaymentMessage],
    config: QueueConfig,
    already_posted_payment_ids: set[str] | None = None,
) -> dict[str, object]:
    _validate_batch_size(messages, config)
    posted_ids = set(already_posted_payment_ids or set())
    successful_payments: list[dict[str, object]] = []
    live_queue: list[PaymentMessage] = []
    backout_queue: list[PaymentMessage] = []
    audit_events: list[dict[str, object]] = []

    for message in sorted_for_processing(messages):
        _process_single(
            message,
            config,
            posted_ids,
            live_queue,
            backout_queue,
            successful_payments,
            audit_events,
        )

    return summarize_mq_run(live_queue, backout_queue, successful_payments, audit_events)


def summarize_mq_run(
    live_queue: list[PaymentMessage],
    backout_queue: list[PaymentMessage],
    successful_payments: list[dict[str, object]],
    audit_events: list[dict[str, object]],
) -> dict[str, object]:
    snapshot = QueueSnapshot(
        live_queue_count=len(live_queue),
        backout_queue_count=len(backout_queue),
        successful_payment_count=len(successful_payments),
        audit_event_count=len(audit_events),
    )
    counts = snapshot.as_dict()
    return {
        "live_queue_count": counts["live_queue_count"],
        "backout_queue_count": counts["backout_queue_count"],
        "successful_payment_count": counts["successful_payment_count"],
        "audit_event_count": counts["audit_event_count"],
        "live_queue": live_queue,
        "backout_queue": backout_queue,
        "successful_payments": successful_payments,
        "audit_events": audit_events,
    }


class MqPaymentConsumer:
    def __init__(self, config: QueueConfig) -> None:
        self.config = config
        self.posted_payment_ids: set[str] = set()

    def process(self, messages: list[PaymentMessage]) -> dict[str, object]:
        result = process_mq_payments(messages, self.config, self.posted_payment_ids)
        for payment in result["successful_payments"]:  # type: ignore[index]
            self.posted_payment_ids.add(str(payment["payment_id"]))
        return result

    def posted_snapshot(self) -> dict[str, object]:
        return {
            "posted_payment_count": len(self.posted_payment_ids),
            "posted_payment_ids": sorted(self.posted_payment_ids),
        }


def process_with_state(
    messages: list[PaymentMessage],
    config: QueueConfig,
    already_posted_payment_ids: set[str] | None = None,
) -> dict[str, object]:
    _validate_batch_size(messages, config)
    state = ProcessingState(config, already_posted_payment_ids)
    for message in sorted_for_processing(messages):
        state.process(message)
    result = state.result()
    return summarize_mq_run(
        result["live_queue"],  # type: ignore[arg-type]
        result["backout_queue"],  # type: ignore[arg-type]
        result["successful_payments"],  # type: ignore[arg-type]
        result["audit_events"],  # type: ignore[arg-type]
    )

