def _require_text(value: str, field_name: str) -> None:
    if not value.strip():
        raise ValueError(f"{field_name} required")


@dataclass(frozen=True)
class PaymentMessage:
    message_id: str
    payment_id: str
    amount_cents: int
    valid_payload: bool
    backout_count: int = 0
    message_type: str = "settlement"
    source_queue: str = "PAYMENT.LIVE"
    correlation_id: str | None = None
    transaction_minute: int = 0

    def __post_init__(self) -> None:
        _require_text(self.message_id, "message_id")
        _require_text(self.payment_id, "payment_id")
        if self.amount_cents <= 0:
            raise ValueError("amount_cents must be positive")
        if self.backout_count < 0:
            raise ValueError("backout_count must be non-negative")
        if self.message_type not in VALID_MESSAGE_TYPES:
            raise ValueError("unsupported message_type")
        _require_text(self.source_queue, "source_queue")
        if self.correlation_id is not None:
            _require_text(self.correlation_id, "correlation_id")
        if self.transaction_minute < 0:
            raise ValueError("transaction_minute must be non-negative")

    def with_backout_count(self, backout_count: int) -> "PaymentMessage":
        return PaymentMessage(
            message_id=self.message_id,
            payment_id=self.payment_id,
            amount_cents=self.amount_cents,
            valid_payload=self.valid_payload,
            backout_count=backout_count,
            message_type=self.message_type,
            source_queue=self.source_queue,
            correlation_id=self.correlation_id,
            transaction_minute=self.transaction_minute,
        )

    def business_key(self) -> str:
        return self.payment_id

    def envelope_key(self) -> str:
        if self.correlation_id is None:
            return self.message_id
        return f"{self.correlation_id}:{self.message_id}"


