class QueueConfig:
    backout_threshold: int
    backout_queue_name: str
    live_queue_name: str = "PAYMENT.LIVE"
    retry_queue_name: str = "PAYMENT.RETRY"
    max_batch_size: int = 100

    def __post_init__(self) -> None:
        if self.backout_threshold <= 0:
            raise ValueError("backout_threshold must be positive")
        _require_text(self.backout_queue_name, "backout_queue_name")
        _require_text(self.live_queue_name, "live_queue_name")
