from __future__ import annotations

from mq_models import PaymentMessage, ProcessingOutcome, QueueConfig, QueueSnapshot, payment_post


def audit(action: str, message: PaymentMessage, reason: str) -> dict[str, object]:
    return ProcessingOutcome(
        message_id=message.message_id,
        payment_id=message.payment_id,
        action=action,
        reason=reason,
        backout_count=message.backout_count,
    ).as_audit()


def increment_backout(message: PaymentMessage) -> PaymentMessage:
    return message.with_backout_count(message.backout_count + 1)


def reset_for_retry(message: PaymentMessage) -> PaymentMessage:
    return PaymentMessage(
        message_id=message.message_id,
        payment_id=message.payment_id,
        amount_cents=message.amount_cents,
        valid_payload=message.valid_payload,
        backout_count=0,
        message_type=message.message_type,
        source_queue=message.source_queue,
        correlation_id=message.correlation_id,
        transaction_minute=message.transaction_minute,
    )


def should_skip_success(message: PaymentMessage, posted_ids: set[str]) -> bool:
    return message.payment_id in posted_ids


def sorted_for_processing(messages: list[PaymentMessage]) -> list[PaymentMessage]:
    return sorted(messages, key=lambda message: (message.transaction_minute, message.message_id))


class QueueAccumulator:
    def __init__(self) -> None:
        self.live_queue: list[PaymentMessage] = []
        self.backout_queue: list[PaymentMessage] = []
        self.successful_payments: list[dict[str, object]] = []
        self.audit_events: list[dict[str, object]] = []

    def post(self, message: PaymentMessage) -> None:
        self.successful_payments.append(payment_post(message))
        self.audit_events.append(audit("payment_posted", message, "valid_payload"))

    def duplicate_success(self, message: PaymentMessage) -> None:
        self.audit_events.append(audit("duplicate_success_skipped", message, "payment_already_posted"))

    def requeue(self, message: PaymentMessage) -> None:
        self.live_queue.append(message)
        self.audit_events.append(audit("requeued_for_retry", message, "payload_validation_failed"))

    def backout(self, message: PaymentMessage) -> None:
        self.backout_queue.append(message)
        self.audit_events.append(audit("moved_to_backout", message, "backout_threshold_reached"))

    def snapshot(self) -> QueueSnapshot:
        return QueueSnapshot(
            live_queue_count=len(self.live_queue),
            backout_queue_count=len(self.backout_queue),
            successful_payment_count=len(self.successful_payments),
            audit_event_count=len(self.audit_events),
        )


class ProcessingState:
    def __init__(self, config: QueueConfig, already_posted_payment_ids: set[str] | None = None) -> None:
        self.config = config
        self.posted_ids = set(already_posted_payment_ids or set())
        self.accumulator = QueueAccumulator()

    def handle_valid(self, message: PaymentMessage) -> None:
        if should_skip_success(message, self.posted_ids):
            self.accumulator.duplicate_success(message)
            return
        self.posted_ids.add(message.payment_id)
        self.accumulator.post(message)

    def handle_invalid(self, message: PaymentMessage) -> None:
        failed_message = reset_for_retry(message)
        if self.config.should_backout(failed_message):
            self.accumulator.backout(failed_message)
        else:
            self.accumulator.requeue(failed_message)

    def process(self, message: PaymentMessage) -> None:
        if message.valid_payload:
            self.handle_valid(message)
            return
        self.handle_invalid(message)

    def result(self) -> dict[str, object]:
        return {
            "live_queue": self.accumulator.live_queue,
            "backout_queue": self.accumulator.backout_queue,
            "successful_payments": self.accumulator.successful_payments,
            "audit_events": self.accumulator.audit_events,
        }

