    def requeue(self, message: PaymentMessage) -> None:
        self.live_queue.append(message)
        self.audit_events.append(audit("requeued_for_retry", message, "payload_validation_failed"))

    def backout(self, message: PaymentMessage) -> None:
        self.backout_queue.append(message)
        self.audit_events.append(audit("moved_to_backout", message, "backout_threshold_reached"))

    def snapshot(self) -> QueueSnapshot:
        return QueueSnapshot(
            live_queue_count=len(self.live_queue),
            backout_queue_count=len(self.backout_queue),
            successful_payment_count=len(self.successful_payments),
            audit_event_count=len(self.audit_events),
        )


class ProcessingState:
    def __init__(self, config: QueueConfig, already_posted_payment_ids: set[str] | None = None) -> None:
        self.config = config
        self.posted_ids = set(already_posted_payment_ids or set())
        self.accumulator = QueueAccumulator()

    def handle_valid(self, message: PaymentMessage) -> None:
        if should_skip_success(message, self.posted_ids):
            self.accumulator.duplicate_success(message)
            return
        self.posted_ids.add(message.payment_id)
        self.accumulator.post(message)

    def handle_invalid(self, message: PaymentMessage) -> None:
        failed_message = reset_for_retry(message)
        if self.config.should_backout(failed_message):
            self.accumulator.backout(failed_message)
        else:
            self.accumulator.requeue(failed_message)

    def process(self, message: PaymentMessage) -> None:
        if message.valid_payload:
            self.handle_valid(message)
            return
        self.handle_invalid(message)

    def result(self) -> dict[str, object]:
        return {
            "live_queue": self.accumulator.live_queue,
            "backout_queue": self.accumulator.backout_queue,
            "successful_payments": self.accumulator.successful_payments,
            "audit_events": self.accumulator.audit_events,
        }
